/**
 * Git-Backed Open Knowledge Format (OKF) Engine v0.2
 * Compliant with Google Cloud OKF v0.2 Specification (https://openknowledgeformat.com/)
 * 
 * Implements the Five Opt-In Trust Signals:
 * 1. Provenance (sources & data lineage)
 * 2. Trust Tiers (generated by vs. verified by human/pipeline)
 * 3. Freshness (effective_date, last_reviewed, stale_after expiration)
 * 4. Lifecycle Status (draft, stable, deprecated)
 * 5. Attestation & Attested Computation (cryptographic SHA-256 and reproducible execution)
 */

export type OkfV02Source = {
  uri: string;
  title: string;
  authority?: string;
};

export type OkfV02Trust = {
  generated: {
    by: "human" | "agent" | "pipeline";
    identity: string;
  };
  verified: {
    by: "human" | "automated";
    identity: string;
    tier: "tier-1-verified" | "tier-2-attested" | "unverified-draft";
  };
};

export type OkfV02Freshness = {
  effective_date: string;
  last_reviewed: string;
  stale_after: string;
};

export type OkfV02Attestation = {
  method: "sha256-gazette-hash" | "git-commit-audit" | "deterministic-runtime-proof";
  upstream_sha256?: string;
  runtime_digest_sha256?: string;
  attested_computation_id?: string;
  reproducible_engine?: string;
  reproducible_environment?: string;
  idempotent?: boolean;
};

export type OkfV02PolicyMeta = {
  okf: "0.2";
  type: "policy" | "attested_computation" | "concept" | "runbook";
  title: string;
  short_name: string;
  description: string;
  category: "MDR_POLICY" | "DISPUTE_RESOLUTION" | "AUTONOMY_GOVERNANCE" | "NIGHTLY_DREAMING" | "ATTESTED_COMPUTATION";
  sources: OkfV02Source[];
  trust: OkfV02Trust;
  freshness: OkfV02Freshness;
  status: "stable" | "draft" | "deprecated";
  attestation: OkfV02Attestation;
  rules?: Record<string, any>;
  computation?: Record<string, any>;
};

export type OkfDocument = {
  filename: string;
  meta: OkfV02PolicyMeta;
  content: string;
};

export type CragEvaluationResult = {
  passed: boolean;
  policyId: string;
  ruleClause: string;
  confidence: number;
  rationale: string;
  sourceFile: string;
  gitCommitSha: string;
  trustSignals: {
    provenance: string;
    trustTier: string;
    freshnessStatus: "FRESH" | "STALE" | "EXPIRING_SOON";
    lifecycleStatus: "stable" | "draft" | "deprecated";
    attestationVerified: boolean;
  };
  calculatedValues: Record<string, number | string | boolean>;
};

