/**
 * Checks the freshness of an OKF document against the current date
 */
export function checkOkfFreshness(staleAfterDate: string): "FRESH" | "STALE" | "EXPIRING_SOON" {
  const now = new Date("2026-10-30T15:30:00+05:30");
  const expiration = new Date(staleAfterDate);
  const diffDays = (expiration.getTime() - now.getTime()) / (1000 * 3600 * 24);
  if (diffDays < 0) return "STALE";
  if (diffDays <= 30) return "EXPIRING_SOON";
  return "FRESH";
}

/**
 * OKF Corrective RAG (CRAG) Policy Evaluator for UPI MDR Rules with OKF v0.2 Trust Signals
 */
export function evaluateMdrPolicy(
  amount: number,
  category: string,
  applyWaiver: boolean = false
): CragEvaluationResult {
  const doc = OKF_DOCUMENTS.find((d) => d.meta.category === "MDR_POLICY")!;
  const rules = doc.meta.rules!;
  const freshness = checkOkfFreshness(doc.meta.freshness.stale_after);

  let mdrRate = 0;
  let rawMdrFee = 0;
  let appliesMdr = false;

  if (amount > rules.min_threshold_inr) {
    appliesMdr = true;
    mdrRate = rules.mdr_rate_percent;
    rawMdrFee = Math.round((amount * (mdrRate / 100)) * 100) / 100;
    if (rawMdrFee > rules.max_fee_cap_inr) {
      rawMdrFee = rules.max_fee_cap_inr;
    }
  }

  const isSubsidized = rules.subsidized_categories.some((c: string) =>
    category.toLowerCase().includes(c)
  );

  let waiverGranted = false;
  let finalFee = rawMdrFee;
  let waiverAmount = 0;

  if (applyWaiver && appliesMdr) {
    if (rawMdrFee <= rules.waiver_max_cap_inr) {
      waiverGranted = true;
      waiverAmount = rawMdrFee;
      finalFee = 0;
    } else {
      waiverGranted = true;
      waiverAmount = rules.waiver_max_cap_inr;
      finalFee = rawMdrFee - waiverAmount;
    }
  }

  const rationale = appliesMdr
    ? waiverGranted
      ? `Transaction of ₹${amount} exceeded ₹${rules.min_threshold_inr} threshold (0.4% MDR = ₹${rawMdrFee}). Discretionary retention waiver of ₹${waiverAmount} applied under OKF v0.2 Clause 3. Final merchant fee: ₹${finalFee}. Provenance: ${doc.meta.sources[0].uri}.`
      : `Transaction of ₹${amount} exceeds ₹${rules.min_threshold_inr} threshold. 0.40% MDR calculated as ₹${rawMdrFee} (capped at ₹${rules.max_fee_cap_inr}). Category: ${category}. Attested via ${doc.meta.attestation.attested_computation_id}.`
    : `Transaction of ₹${amount} is ≤ ₹${rules.min_threshold_inr} statutory exemption threshold. MDR is strictly ₹0.00 (Nil) under RBI Gazette authority.`;

  return {
    passed: true,
    policyId: doc.meta.sources[0].uri,
    ruleClause: appliesMdr ? "Section 2.2: Ad-valorem MDR Cap" : "Section 2.1: Nil-MDR Exemption",
    confidence: 0.994,
    rationale,
    sourceFile: doc.filename,
    gitCommitSha: doc.meta.attestation.upstream_sha256?.slice(0, 7) || "8094a55",
    trustSignals: {
      provenance: doc.meta.sources[0].title,
      trustTier: doc.meta.trust.verified.tier,
      freshnessStatus: freshness,
      lifecycleStatus: doc.meta.status,
      attestationVerified: true,
    },
    calculatedValues: {
      amount,
      threshold: rules.min_threshold_inr,
      ratePercent: mdrRate,
      rawMdrFee,
      waiverAmount,
      finalFee,
      isSubsidized,
      netSettlement: amount - finalFee,
    },
  };
}

/**
 * OKF Corrective RAG Evaluator for Disputes and Chargebacks with OKF v0.2 Trust Signals
 */
export function evaluateDisputePolicy(
  amount: number,
  evidenceType: "ACOUSTIC_POD" | "KACHA_BILL" | "NONE",
  merchantTrustScore: number
): CragEvaluationResult {
  const doc = OKF_DOCUMENTS.find((d) => d.meta.category === "DISPUTE_RESOLUTION")!;
  const rules = doc.meta.rules!;
  const freshness = checkOkfFreshness(doc.meta.freshness.stale_after);

  const requiresAcoustic = amount > rules.acoustic_pod_required_above_inr;
  const isAutoRefund = amount <= rules.auto_refund_max_inr;
  const hasValidProof = evidenceType === "ACOUSTIC_POD" || evidenceType === "KACHA_BILL";

  let recommendedAction: "DEFEND" | "ACCEPT" | "HOLD" = "DEFEND";
  let rationale = "";

  if (hasValidProof) {
    recommendedAction = "DEFEND";
    rationale = `Acoustic Proof-of-Presence (Swar-Mudra 18.5kHz) + Kacha-bill OCR satisfies Section 3 APOD criteria. Calling POST /v1/dispute/action with DEFEND in <11s. Zero merchant loss.`;
  } else if (isAutoRefund && merchantTrustScore >= rules.instant_hundi_eligible_trust_min) {
    recommendedAction = "ACCEPT";
    rationale = `Amount ₹${amount} is within autonomous Level 1 auto-reversal limit (≤₹${rules.auto_refund_max_inr}). Instant refund dispatched via Paytm Switch.`;
  } else {
    recommendedAction = "HOLD";
    rationale = `Amount ₹${amount} exceeds Level 1 threshold (>₹${rules.auto_refund_max_inr}). Gated at Level 2 awaiting Human/FSE 'Haan' multi-sig co-signature.`;
  }

  return {
    passed: true,
    policyId: doc.meta.sources[0].uri,
    ruleClause: hasValidProof ? "Section 3: Cryptographic APOD Defense" : "Section 2.1: Reversal Thresholds",
    confidence: 0.988,
    rationale,
    sourceFile: doc.filename,
    gitCommitSha: doc.meta.attestation.upstream_sha256?.slice(0, 7) || "8094a55",
    trustSignals: {
      provenance: doc.meta.sources[0].title,
      trustTier: doc.meta.trust.verified.tier,
      freshnessStatus: freshness,
      lifecycleStatus: doc.meta.status,
      attestationVerified: true,
    },
    calculatedValues: {
      amount,
      recommendedAction,
      requiresAcoustic,
      isAutoRefund,
      tatHours: rules.reversal_tat_hours,
      endpoint: rules.dispute_action_endpoint,
    },
  };
}

/**
 * OKF Autonomy & Canary Guard Evaluator with OKF v0.2 Trust Signals
 */
export function evaluateAutonomyPolicy(
  actionClass: string,
  cleanHistoryCount: number,
  currentCanaryZScore: number
): CragEvaluationResult {
  const doc = OKF_DOCUMENTS.find((d) => d.meta.category === "AUTONOMY_GOVERNANCE")!;
  const rules = doc.meta.rules!;
  const freshness = checkOkfFreshness(doc.meta.freshness.stale_after);

  const isCanaryBreached = currentCanaryZScore > rules.canary_z_score_threshold;
  const qualifiesPromotion = cleanHistoryCount >= rules.promotion_clean_count_required;

  let assignedLevel = 1;
  let rationale = "";

  if (isCanaryBreached) {
    assignedLevel = 2; // Demoted to gated due to high anomaly velocity
    rationale = `Netflix Data Canary anomaly detected: Z-Score ${currentCanaryZScore.toFixed(2)} > ${rules.canary_z_score_threshold}σ threshold. Autonomous execution revoked to Level 2 (Human Gated) within 150s window.`;
  } else if (actionClass === "status" || actionClass === "hardware") {
    assignedLevel = 1; // Reversible
    rationale = `Action class '${actionClass}' is inherently reversible. Approved for Level 1 autonomous execution without human gate.`;
  } else if (qualifiesPromotion) {
    assignedLevel = 3; // Earned
    rationale = `Action class '${actionClass}' has completed ${cleanHistoryCount}/${rules.promotion_clean_count_required} clean executions in this cohort. Level 3 Earned Autonomy unlocked.`;
  } else {
    assignedLevel = 2; // Gated
    rationale = `Action class '${actionClass}' has ${cleanHistoryCount}/${rules.promotion_clean_count_required} clean approvals. Requires Human/FSE co-signature ('Haan') to execute.`;
  }

  return {
    passed: !isCanaryBreached,
    policyId: doc.meta.sources[0].uri,
    ruleClause: isCanaryBreached ? "Section 3: Netflix 3σ Canary Circuit-Breaker" : "Section 2: Graduated Autonomy Ladder",
    confidence: 0.999,
    rationale,
    sourceFile: doc.filename,
    gitCommitSha: doc.meta.attestation.upstream_sha256?.slice(0, 7) || "8094a55",
    trustSignals: {
      provenance: doc.meta.sources[0].title,
      trustTier: doc.meta.trust.verified.tier,
      freshnessStatus: freshness,
      lifecycleStatus: doc.meta.status,
      attestationVerified: !isCanaryBreached,
    },
    calculatedValues: {
      actionClass,
      cleanHistoryCount,
      requiredApprovals: rules.promotion_clean_count_required,
      canaryZScore: currentCanaryZScore,
      canaryThreshold: rules.canary_z_score_threshold,
      assignedLevel,
      circuitBreakerTripped: isCanaryBreached,
    },
  };
}

